export function percentOff(total, pct) {
  return Math.round(total * (100 - pct)) / 100;
}

// Single code table. Months are 0-based; expiry is inclusive, local time.
const CODES = {
  SAVE10: { type: 'percent', value: 10 },
  FIVE: { type: 'flat', value: 5 },
  WINTER: {
    type: 'percent',
    value: 20,
    expiresAt: new Date(2024, 11, 31, 23, 59, 59, 999),
  },
};

export function applyCode(total, code, now) {
  if (typeof total !== 'number' || !Number.isFinite(total) || total < 0) {
    return { ok: false, total, reason: 'invalid-total' };
  }
  const key = typeof code === 'string' ? code.trim().toUpperCase() : '';
  const def = Object.hasOwn(CODES, key) ? CODES[key] : undefined;
  if (!def) {
    return { ok: false, total, reason: 'invalid-code' };
  }
  if (def.expiresAt) {
    if (!(now instanceof Date) || Number.isNaN(now.getTime())) {
      return { ok: false, total, reason: 'invalid-date' };
    }
    if (now.getTime() > def.expiresAt.getTime()) {
      return { ok: false, total, reason: 'expired' };
    }
  }
  const result =
    def.type === 'percent'
      ? percentOff(total, def.value)
      : Math.max(0, Math.round((total - def.value) * 100) / 100);
  return { ok: true, total: result, reason: null };
}

