const WINTER_END = new Date(2024, 11, 31, 23, 59, 59, 999); // 2024-12-31 end of day (local time)

export function applyCode(total, code, now = new Date()) {
  const key = typeof code === 'string' ? code.trim().toUpperCase() : '';
  switch (key) {
    case 'SAVE10':
      return { ok: true, total: percentOff(total, 10) };
    case 'FIVE':
      return { ok: true, total: Math.max(0, Math.round((total - 5) * 100) / 100) };
    case 'WINTER':
      if (now > WINTER_END) return { ok: false, total, reason: 'expired' };
      return { ok: true, total: percentOff(total, 20) };
    default:
      return { ok: false, total, reason: 'unknown code' };
  }
}

