import test from 'node:test';
import assert from 'node:assert/strict';
import { makeUser } from '../src/users.js';
import { userResponse } from '../src/api/user-api.js';
import { userCard } from '../src/ui/user-card.js';
import { userCsv } from '../src/export/user-export.js';

const base = { id: 1, name: 'Ann', email: 'ann@x.io' };
const withPhone = makeUser({ ...base, phone: '555-1234' });
const without = makeUser(base);

test('makeUser includes phone only when provided', () => {
  assert.equal(withPhone.phone, '555-1234');
  assert.equal('phone' in without, false);
  assert.equal('phone' in makeUser({ ...base, phone: '' }), false);
  assert.equal('phone' in makeUser({ ...base, phone: null }), false);
});

test('userResponse with phone', () => {
  assert.deepEqual(userResponse(withPhone), { ...base, phone: '555-1234' });
});

test('userResponse without phone omits key', () => {
  assert.equal('phone' in userResponse(without), false);
});

test('userCard with and without phone', () => {
  assert.equal(userCard(withPhone), 'Ann <ann@x.io> · 555-1234');
  assert.equal(userCard(without), 'Ann <ann@x.io>');
});

test('userCsv with and without phone', () => {
  assert.equal(userCsv(withPhone), '1,Ann,ann@x.io,555-1234');
  assert.equal(userCsv(without), '1,Ann,ann@x.io,');
});
